/**
 * Fact-check ledger.
 *
 * The automated briefing archives in `src/data/post/` are immutable (their
 * SHA-256 hashes are pinned in docs/briefing-archive-manifest.json), so
 * verification verdicts are recorded here instead, keyed by the translation
 * group (`translationKey`) so both the English original and any translation
 * render the same panel. Only records where every verdict names public sources
 * are publication-ready; incomplete research records stay internal.
 */

export type FactCheckVerdict = 'supported' | 'partially_supported' | 'unsupported' | 'unresolvable';

export interface FactCheckClaim {
  /** The claim as the briefing states it, summarized. */
  claim: string;
  verdict: FactCheckVerdict;
  /** What the public record shows, including framing errors. */
  note: string;
  /** Public sources consulted for this verdict; empty means the record is incomplete and must not be published. */
  sources: string[];
}

export interface FactCheckRecord {
  translationKey: string;
  checkedAt: string;
  checkedBy: string;
  summary: string;
  claims: FactCheckClaim[];
}

