/** A public fact-check must give every reviewed claim at least one source. */
export const isFactCheckComplete = (record: FactCheckRecord): boolean =>
  record.claims.length > 0 && record.claims.every((claim) => claim.sources.length > 0);

const factChecksByTranslationKey = new Map(factChecks.map((record) => [record.translationKey, record]));

/** Looks up a publication-ready fact-check record for a translation group. */
export const getFactCheck = (translationKey?: string): FactCheckRecord | undefined => {
  if (!translationKey) return undefined;
  const record = factChecksByTranslationKey.get(translationKey);
  return record && isFactCheckComplete(record) ? record : undefined;
};
